#include <vector>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int P = 1;
    #pragma omp parallel
    {
        #pragma omp single
        { P = omp_get_num_threads(); }
    }

    std::vector<double> blockSums((std::size_t)P + 1, 0.0); // blockSums[t+1] = sum of block t

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const std::size_t start = (n * (std::size_t)tid) / (std::size_t)nt;
        const std::size_t end   = (n * (std::size_t)(tid + 1)) / (std::size_t)nt;

        // Local inclusive scan for this block into output
        double sum = 0.0;
        for (std::size_t i = start; i < end; ++i) {
            sum += x[i];
            output[i] = sum;
        }

        // Publish block sum (single-writer per slot)
        blockSums[(std::size_t)tid + 1] = sum;

        #pragma omp barrier

        // One thread computes offsets (exclusive prefix of block sums)
        #pragma omp single
        {
            for (int t = 1; t <= nt; ++t) {
                blockSums[(std::size_t)t] += blockSums[(std::size_t)t - 1];
            }
        }

        #pragma omp barrier

        // Add offset to each element in this block (offset excludes this block's own sum)
        const double offset = blockSums[(std::size_t)tid];
        for (std::size_t i = start; i < end; ++i) {
            output[i] += offset;
        }
    }
}
